import json
import glob

all_polymorphs = []

# Get all JSON files
json_files = glob.glob("polymorph_data/*_polymorphs.json")

for json_file in json_files:
    try:
        with open(json_file, 'r') as f:
            file_data = json.load(f)
            if isinstance(file_data, list):
                all_polymorphs.extend(file_data)
    except:
        pass

filtered_data = all_polymorphs
